public boolean canAttendMeetings(int[][] intervals) {
    int n = intervals.length;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (intervals[i][0] < intervals[j][1] &&
                intervals[j][0] < intervals[i][1]) {
                return false;
            }
        }
    }
    return true;
}

